extra_css:
/* Supercell surfaces: storm glass. Panels are dark slate with a cold rim and a faint dusk glow along the lower edge, as if lit from
   the burning horizon under the storm; hover sends a quick flash across the rim. Scoped to own surfaces only. */
html[data-atmo="supercell"] .card, html[data-atmo="supercell"] .panel, html[data-atmo="supercell"] .gx-card {
  background: linear-gradient(180deg, rgba(27,34,48,.86), rgba(10,13,19,.93) 78%, rgba(60,30,18,.5));
  backdrop-filter: blur(12px); -webkit-backdrop-filter: blur(12px);
  box-shadow: inset 0 1px 0 rgba(214,228,255,.10), inset 0 0 0 1px rgba(169,200,255,.12), inset 0 -10px 22px -16px rgba(255,140,70,.35), 0 18px 46px rgba(0,0,0,.7);
  transition: box-shadow .35s ease, transform .5s cubic-bezier(.2,1,.3,1); }
html[data-atmo="supercell"] .card:hover, html[data-atmo="supercell"] .gx-card:hover {
  transform: translateY(-2px); box-shadow: inset 0 1px 0 rgba(214,228,255,.22), inset 0 0 0 1px rgba(169,200,255,.45), 0 0 26px rgba(169,200,255,.14), 0 22px 54px rgba(0,0,0,.75); }
html[data-atmo="supercell"] h1, html[data-atmo="supercell"] h2 { background: linear-gradient(180deg, #ffffff, #c9dbff 50%, #7f9cc9); -webkit-background-clip: text; background-clip: text; color: transparent; }

